class PolicyModule(ModuleBase):
    def forward(self, state: State, buffers: Dict[str, Any], t: int) -> None:
        # Prefer same-day prevalence from DiseaseDynamics, fallback to prior state
        prev = float(buffers.get("prevalence", sum(1 for p in state.people if p.health_status == "I") / max(1, len(state.people))))
        # Accept spec alias mandate_day
        start_day = int(self.params.get("mandate_start_day", self.params.get("mandate_day", -1)))
        coverage = set(self.params.get("mandate_coverage", ["workplace", "retail", "transit", "public"]))
        prev_state = state.policy.policy_state
        new_state = prev_state
        if start_day >= 0 and t >= start_day:
            new_state = "mandate"
        else:
            tighten = float(self.params.get("policy_trigger_prevalence", 0.02))
            relax = float(self.params.get("policy_relaxation_prevalence", 0.005))
            if prev >= tighten:
                new_state = "mandate"
            elif prev <= relax:
                new_state = "recommended"
        if new_state != prev_state:
            buffers.setdefault("policy_change_events", []).append((t, prev_state, new_state))
        buffers["new_policy_state"] = new_state
        buffers["locations_policy"] = {loc.id: (new_state == "mandate" and loc.type in coverage) for loc in state.locations}
        buffers["mandate_active_today"] = 1 if new_state == "mandate" else 0

